const byId = id => document.getElementById(id);
const API = ['127.0.0.1','localhost'].includes(location.hostname)?'':'http://127.0.0.1:5174';
let starting, base, result, beforeAlignment, working=false, generation=0;
const fields=['angle-mode','h-min','h-max','v-min','v-max','ext-max','ext-step'];
async function call(action,snapshot,options={}) {
  const response=await fetch(API+'/api/workflow',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,snapshot,options}),signal:AbortSignal.timeout(600000)});
  const data=await response.json();if(!response.ok)throw Error(data.error||'Continuation failed');return data;
}
function message(text,error=false){byId('continuation-status').textContent=text;byId('continuation-status').classList.toggle('error',error);}
function lock(value){working=value;document.querySelectorAll('#continuation-page button,#continuation-page input,#continuation-page select').forEach(el=>el.disabled=value);byId('back-start').disabled=false;if(!value){custom();byId('c-before').disabled=!beforeAlignment;for(const id of ['align-strands','apply-extensions','preview-angles','c-json','c-png'])byId(id).disabled=!result;}}
function custom(){document.querySelectorAll('.custom-angle').forEach(el=>el.disabled=working||byId('angle-mode').value!=='custom');}
function options(){return {mode:byId('angle-mode').value,hMin:+byId('h-min').value,hMax:+byId('h-max').value,vMin:+byId('v-min').value,vMax:+byId('v-max').value,maximum:+byId('ext-max').value,step:+byId('ext-step').value,extensions:Object.fromEntries([...document.querySelectorAll('[data-pair]')].map(el=>[el.dataset.pair,+el.value]))};}
function page(){const continuation=location.hash==='#continuation'&&starting;byId('starting-page').hidden=!!continuation;byId('continuation-page').hidden=!continuation;document.title=continuation?'Continuation — MxN Strand Studio':'Starting stitch — MxN Strand Studio';}
window.addEventListener('hashchange',()=>{page();window.scrollTo(0,0);});
byId('back-start').onclick=()=>{location.hash='starting-stitch';};
function pairs(data){byId('pair-extensions').replaceChildren();for(const pair of data.pairs||[]){const label=document.createElement('label');label.className='field';label.textContent=`${pair.axis} · ${pair.labels.join(' ↔ ')} · px`;const input=document.createElement('input');input.type='number';input.min=-200;input.max=500;input.value=0;input.step=4;input.dataset.pair=pair.key;label.append(input);byId('pair-extensions').append(label);}}
function drawGuides(){const svg=byId('angle-overlay');svg.replaceChildren();if(!result||!byId('show-angles').checked)return;const b=result.bounds;svg.setAttribute('viewBox',`${b.x} ${b.y} ${b.width} ${b.height}`);for(const [axis,r] of Object.entries(result.ranges||{})){if(!r)continue;for(const [index,start] of [r.first_start,r.last_start].entries()){for(const angle of [r.angle_min,r.angle_max]){const rad=(angle+(index?180:0))*Math.PI/180;const line=document.createElementNS('http://www.w3.org/2000/svg','line');for(const [k,v] of Object.entries({x1:start.x,y1:start.y,x2:start.x+180*Math.cos(rad),y2:start.y+180*Math.sin(rad),stroke:axis==='horizontal'?'#bd613e':'#226bc0','stroke-width':3,'stroke-dasharray':'9 5'}))line.setAttribute(k,v);svg.append(line);}}}}
function paint(data){result=data;byId('continuation-image').src=`data:image/png;base64,${data.png}`;byId('continuation-image').alt=`${starting.settings.m} by ${starting.settings.n} continuation rendered by OpenStrandStudio`;byId('c-animals').checked=data.settings.animals;byId('c-names').checked=data.settings.names;if(data.ranges){for(const [axis,name] of [['h','horizontal'],['v','vertical']]){const r=data.ranges[name];if(r&&byId('angle-mode').value!=='custom'){byId(axis+'-min').value=r.angle_min.toFixed(1);byId(axis+'-max').value=r.angle_max.toFixed(1);}}}drawGuides();}
async function operate(action){if(working||!base)return;if(!byId('continuation-form').reportValidity())return;const opts=options();if(opts.mode==='custom'&&(opts.hMin>opts.hMax||opts.vMin>opts.vMax)){message('Minimum angles must not exceed maximum angles.',true);return;}lock(true);message(action==='align'?'Searching horizontal and vertical alignments… This can take a few minutes.':'Updating continuation…');try{const display={animals:byId('c-animals').checked,names:byId('c-names').checked};const previous=action==='align'?await call('extend',base.snapshot,opts):null;let data=await call(action,base.snapshot,opts);if(data.settings.animals!==display.animals||data.settings.names!==display.names){const shown=await call('display',data.snapshot,display);data={...data,...shown};}if(action==='align'){beforeAlignment=previous;paint(data);const report=data.alignment.map(r=>`${r.axis.toUpperCase()}: ${r.success?'aligned':r.fallback?'best partial match':'no solution'}${r.angle!=null?` · ${r.angle.toFixed(1)}°`:''}${r.gap!=null?` · gap ${r.gap.toFixed(1)} px`:''}`).join(' / ');message(report);byId('c-badge').textContent=data.alignment.every(r=>r.success)?'ALIGNED':'PARTIAL RESULT';}else{beforeAlignment=null;paint(data);message('Continuation updated · Ready to align');byId('c-badge').textContent='CONTINUATION';}}catch(e){message(e.message,true);}finally{lock(false);}}
window.openContinuation=async data=>{starting=data;const id=++generation;base=null;result=null;beforeAlignment=null;byId('continuation-image').removeAttribute('src');byId('angle-overlay').replaceChildren();location.hash='continuation';page();window.scrollTo(0,0);byId('starting-reference').src=`data:image/png;base64,${data.png}`;const p=data.settings;byId('inherited-settings').textContent=`${p.m} × ${p.n} · ${p.hand==='lh'?'Left-hand / CW':'Right-hand / CCW'} · k=${p.k>=0?'+':''}${p.k}`;byId('continuation-title').textContent=`${p.m} × ${p.n} / Continuation`;byId('angle-mode').value='first_strand';byId('c-badge').textContent='CONTINUATION';lock(true);message('Creating continuation from your starting stitch…');try{const next=await call('continue',data.snapshot);if(id!==generation)return;base=next;pairs(next);paint(next);message(p.stretch?'Continuation ready · Pairing uses your k offset':'Continuation ready · Outer strands extended as required by MxN');}catch(e){message(e.message,true);}finally{lock(false);}};
byId('align-strands').onclick=()=>operate('align');byId('preview-angles').onclick=()=>{byId('show-angles').checked=true;operate('preview');};byId('apply-extensions').onclick=()=>operate('extend');byId('c-retry').onclick=()=>starting&&window.openContinuation(starting);
byId('show-angles').onchange=drawGuides;byId('angle-mode').onchange=()=>{custom();message('Angle mode changed · Preview ranges or Align to apply');};
for(const id of fields)byId(id).addEventListener('input',()=>message('Settings changed · Apply extensions, preview angles, or Align to update'));
byId('c-before').onclick=()=>{if(beforeAlignment){const swap=result;paint(beforeAlignment);beforeAlignment=swap;const aligned=result.alignment?.length;byId('c-badge').textContent=aligned?(result.alignment.every(r=>r.success)?'ALIGNED':'PARTIAL RESULT'):'BEFORE ALIGNMENT';message(aligned?'Showing alignment result':'Showing continuation before alignment');}};
for(const id of ['c-animals','c-names'])byId(id).onchange=async()=>{if(working||!result)return;lock(true);try{const old=result,data=await call('display',result.snapshot,{animals:byId('c-animals').checked,names:byId('c-names').checked});paint({...data,ranges:old.ranges,pairs:old.pairs,alignment:old.alignment});message('Display updated');}catch(e){message(e.message,true);}finally{lock(false);}};
function download(blob,extension){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`mxn-${starting.settings.m}x${starting.settings.n}-continuation.${extension}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
byId('c-json').onclick=()=>result&&download(new Blob([JSON.stringify(result.document,null,2)],{type:'application/json'}),'json');
byId('c-png').onclick=async()=>{if(!result||working)return;lock(true);try{const data=await call('display',result.snapshot,{scale:+byId('c-scale').value,transparent:byId('c-transparent').checked});download(new Blob([Uint8Array.from(atob(data.png),c=>c.charCodeAt(0))],{type:'image/png'}),'png');message('Continuation PNG downloaded');}catch(e){message(e.message,true);}finally{lock(false);}};
page();
